from itertools import combinations

def check_solution_full(schedule, W=8, G=10, S=3):
    N = G * S
    pair_count = {}

    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(N):
            g = schedule[w][p]
            groups[g].append(p)

        for g in range(G):
            if len(groups[g]) != S:
                return False, f"Week {w}, group {g} has {len(groups[g])} players"

        for g in range(G):
            for p1, p2 in combinations(groups[g], 2):
                pair = (min(p1,p2), max(p1,p2))
                pair_count[pair] = pair_count.get(pair, 0) + 1
                if pair_count[pair] > 1:
                    return False, f"Pair {pair} meets more than once (week {w}, group {g})"

    return True, f"Valid! {len(pair_count)} unique pairs used"

